describe('Snackbar Notification after Copying Text', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to your application's base URL
    });

    it('should display snackbar message after copying text to clipboard', () => {
        cy.get('.copy-text-button').click(); // Adjust the selector to your copy button
        cy.get('.snackbar').should('be.visible').and('contain', 'Text copied to clipboard!');
    });

    it('should not display snackbar message if copy action fails', () => {
        // Simulate a failure in copying text
        cy.intercept('POST', '/copy-text', { statusCode: 500 }).as('copyText');
        cy.get('.copy-text-button').click();
        cy.wait('@copyText');
        cy.get('.snackbar').should('not.exist');
    });
});
